const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point = ee.Geometry.Point([-87.160422, 56.271030]);
  const region = point.buffer(5000); // 5km buffer around point

  const date1 = '2020-07-13';
  const date2 = '2020-07-29';

  // 2. Data Acquisition - Sentinel-2 for sea ice detection
  function getCollection(date) {
    return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(region)
      .filterDate(date, ee.Date(date).advance(1, 'day'))
      .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80));
  }

  const col1 = getCollection(date1);
  const col2 = getCollection(date2);

  // Check collection sizes
  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`July 13 Images: ${size1}, July 29 Images: ${size2}`);

  if (size1 === 0 || size2 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get least cloudy image for each date
  const img1 = col1.sort('CLOUDY_PIXEL_PERCENTAGE').first();
  const img2 = col2.sort('CLOUDY_PIXEL_PERCENTAGE').first();

  // 3. Sea ice detection using reflectance - ice has high reflectance in blue/green bands
  function detectSeaIce(img) {
    // Use blue band (B2) for ice detection - ice has high reflectance
    const blue = img.select('B2');
    // Simple threshold: values > 2000 likely indicate ice/snow
    const iceMask = blue.gt(2000);
    return iceMask.rename('ice');
  }

  const ice1 = detectSeaIce(img1);
  const ice2 = detectSeaIce(img2);

  // 4. Count ice pixels
  const count1 = ice1.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  }).get('ice').getInfo();

  const count2 = ice2.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: region,
    scale: 100,
    maxPixels: 1e9
  }).get('ice').getInfo();

  console.log(`July 13 ice pixels: ${Math.round(count1)}, July 29 ice pixels: ${Math.round(count2)}`);

  // Check for valid pixels
  if (count1 === null || count2 === null || isNaN(count1) || isNaN(count2)) {
    console.log("<answer>C3</answer>");
    return;
  }

  if (count1 === 0 && count2 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Final comparison
  if (count2 > count1) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
